"""Migration of legacy OPP_MASTER validation rules."""

from decimal import Decimal
from typing import Any


def _value(row: dict | None, field: str) -> Any:
    if row is None:
        return ""
    value = row.get(field, "")
    return "" if value is None else value


def _nvl(value: Any, default: Any) -> Any:
    return default if value is None or value == "" else value


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _date_equals(left: Any, right: Any) -> bool:
    left = "" if left is None else str(left)
    right = "" if right is None else str(right)
    if left == "00000000" or right == "00000000":
        return left == "00000000" and right == "00000000"
    return left == right


def _date_greater_or_equal(left: Any, right: Any) -> bool:
    left = "" if left is None else str(left)
    right = "" if right is None else str(right)
    if left == "00000000" or right == "00000000":
        return False
    return left >= right


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an OPP_MASTER post-write image in legacy rule-file order."""
    errors: list[dict] = []

    amt = _value(record, "AMT")
    stat_cd = _value(record, "STAT_CD")
    lost_rsn = _value(record, "LOST_RSN")
    close_dt = _value(record, "CLOSE_DT")
    stage_pct = _value(record, "STAGE_PCT")

    def add(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append({"code": code, "message": message, "severity": severity})

    if event in ("INSERT", "UPDATE"):
        if _number(_nvl(amt, 0)) < Decimal("0"):
            add("E3001", "Amount negative")

        if stat_cd == "W" and _number(_nvl(amt, 0)) == Decimal("0"):
            add("E3002", "Won opportunity requires amount")

        if stat_cd == "L" and lost_rsn == "":
            add("E3003", "Lost reason required")

        if stat_cd == "W" and _date_equals(close_dt, "00000000"):
            add("E3004", "Won opportunity requires close date")

    if event == "UPDATE":
        old_stat_cd = _value(old, "STAT_CD")
        if old_stat_cd == "W" and stat_cd != "W":
            add("E3005", "Cannot reopen a won opportunity")

    if event in ("INSERT", "UPDATE"):
        stage_matches_status = (
            (stat_cd == "P" and _number(stage_pct) == Decimal("10"))
            or (stat_cd == "Q" and _number(stage_pct) == Decimal("25"))
            or (stat_cd == "N" and _number(stage_pct) == Decimal("60"))
            or (stat_cd == "W" and _number(stage_pct) == Decimal("100"))
            or (stat_cd == "L" and _number(stage_pct) == Decimal("0"))
        )
        if not stage_matches_status:
            add("E3006", "Stage percent inconsistent with status")

    if event == "INSERT":
        if not (
            _date_equals(close_dt, "00000000")
            or _date_greater_or_equal(close_dt, today)
        ):
            add("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
